INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-HORSE', 'Horse', 'Equine', 'Animal', 'Large', 8, 3, 'Large hoofed mammal characterized by powerful legs, a long neck, a mane and tail, and a body adapted for sustained terrestrial movement. Horses may exist as wild or domesticated populations and show substantial variation in build, coloration, and physical proportions.', 'Social herd animal with strong flight instincts. Horses generally avoid threats when possible but may defend themselves through kicking, biting, trampling, or striking with the forelegs when cornered or protecting themselves or their herd.', 'Grasslands, plains, open woodland, agricultural regions, and other environments capable of supporting sufficient forage and water. Domesticated populations can occur anywhere their needs are supported.', '', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-PEGASUS', 'Pegasus', 'Equine', 'Magical Beast', 'Large', 12, 5, 'Winged equine creature with the general body plan of a horse and a pair of large functional wings adapted for sustained flight.', 'Social and alert, with strong herd instincts and a tendency to avoid unnecessary danger. Uses flight to escape threats or gain positional advantage.', 'Open highlands, broad grasslands, mountain valleys, and other regions with sufficient open space for takeoff and landing.', 'PROPOSED FOR REVIEW — stress-test creature; not canon until approved.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-DRAGON', 'Dragon', 'Draconic', 'Magical Beast', 'Huge', 30, 24, 'Large winged reptilian creature with powerful limbs, a long neck and tail, natural weapons, and the capacity for an innate breath attack.', 'Territorial, intelligent, and highly dangerous. Behavior may vary greatly by individual, age, and circumstance.', 'Remote mountains, caverns, ruins, volcanic regions, wilderness territories, and other defensible lairs.', 'PROPOSED FOR REVIEW — generic dragon stress test; breath type, armor, and deeper dragon taxonomy intentionally unresolved.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-SLIME', 'Slime', 'Ooze', 'Ooze', 'Medium', 14, 6, 'Amorphous gelatinous organism lacking fixed limbs, bones, and conventional internal anatomy.', 'Moves slowly toward food, warmth, magic, vibration, or other stimuli depending on the individual type. Does not rely on a conventional humanoid body plan.', 'Caves, ruins, sewers, marshes, underground complexes, and other damp or enclosed environments.', 'PROPOSED FOR REVIEW — stress test for shared hit-location pools and amorphous anatomy.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-GHOST', 'Ghost', 'Spirit', 'Spirit', 'Medium', 22, 14, 'Incorporeal spirit retaining a recognizable identity or form without possessing an ordinary physical body.', 'Varies with identity, memory, purpose, and circumstances of manifestation. May observe, communicate, flee, haunt, or attack.', 'Locations associated with death, strong memory, supernatural disturbance, unfinished purpose, or other spiritual anchors.', 'PROPOSED FOR REVIEW — stress test for creatures whose physical hit locations may be not applicable.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-DOG', 'Dog', 'Canine', 'Animal', 'Small', 4, 1, 'Domesticated canine with wide variation in build, coat, and temperament.', 'Social and responsive to familiar groups; behavior ranges from cautious to defensive or predatory depending on circumstances.', 'Human settlements, farms, camps, and feral populations in many climates.', 'PROPOSED FOR REVIEW — copyright-safe catalog draft; mechanics and wording are independently authored for Serrian Tide.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-WOLF', 'Wolf', 'Canine', 'Animal', 'Medium', 8, 3, 'Large wild canine adapted for endurance travel, coordinated hunting, and powerful biting.', 'Usually social and pack-oriented; avoids needless risk but may pursue prey cooperatively.', 'Forests, tundra, grasslands, mountains, and other broad wilderness habitats.', 'PROPOSED FOR REVIEW — copyright-safe catalog draft; mechanics and wording are independently authored for Serrian Tide.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-COYOTE', 'Coyote', 'Canine', 'Animal', 'Small', 5, 2, 'Adaptable wild canine smaller than a wolf and capable of surviving close to settled areas.', 'Opportunistic, wary, and mobile; hunts small prey and scavenges when useful.', 'Grasslands, deserts, forests, farmland, and urban fringes.', 'PROPOSED FOR REVIEW — copyright-safe catalog draft; mechanics and wording are independently authored for Serrian Tide.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-RED-FOX', 'Red Fox', 'Canine', 'Animal', 'Small', 3, 1, 'Small agile canine with a narrow muzzle, bushy tail, and strong hunting senses.', 'Solitary or loosely social; relies on stealth and quick movement rather than direct confrontation.', 'Woodland, grassland, farmland, tundra, and settled fringes.', 'PROPOSED FOR REVIEW — copyright-safe catalog draft; mechanics and wording are independently authored for Serrian Tide.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-LION', 'Lion', 'Feline', 'Animal', 'Large', 12, 5, 'Powerful social big cat built for short explosive attacks and grappling prey.', 'Often lives and hunts socially; stalks before committing to a rapid close attack.', 'Savannas, open woodland, scrub, and grassland.', 'PROPOSED FOR REVIEW — copyright-safe catalog draft; mechanics and wording are independently authored for Serrian Tide.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-TIGER', 'Tiger', 'Feline', 'Animal', 'Large', 13, 5, 'Very large solitary cat combining strength, stealth, and strong swimming ability.', 'Typically solitary and territorial; ambushes prey from cover and disengages when a fight is unfavorable.', 'Forests, wetlands, grasslands, and dense cover across suitable climates.', 'PROPOSED FOR REVIEW — copyright-safe catalog draft; mechanics and wording are independently authored for Serrian Tide.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-LEOPARD', 'Leopard', 'Feline', 'Animal', 'Medium', 10, 4, 'Powerful spotted cat notable for stealth, climbing strength, and explosive ambush attacks.', 'Solitary and secretive; frequently uses trees or broken terrain to avoid stronger competitors.', 'Forests, savannas, mountains, scrub, and rocky country.', 'PROPOSED FOR REVIEW — copyright-safe catalog draft; mechanics and wording are independently authored for Serrian Tide.', 'serrian-tide-creature-canon');
