INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-COCKATRICE', 'Cockatrice', 'Cockatrice', 'Magical Beast', 'Small', 12, 5, 'Small monstrous bird-reptile associated in folklore with unnatural venom, curses, or petrifying harm.', 'Skittish but vicious when cornered; attacks with pecks, bites, and sudden supernatural effects.', 'Ruins, abandoned farms, rocky scrub, and old underground spaces.', 'PROPOSED FOR REVIEW — copyright-safe catalog draft; mechanics and wording are independently authored for Serrian Tide.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-CHIMERA', 'Chimera', 'Chimera', 'Magical Beast', 'Large', 23, 15, 'Composite monster bearing multiple animal aspects and several natural weapons on one powerful body.', 'Aggressive and territorial; shifts between heads and limbs to pressure several threats at once.', 'Mountains, badlands, caverns, and isolated wild regions.', 'PROPOSED FOR REVIEW — copyright-safe catalog draft; mechanics and wording are independently authored for Serrian Tide.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-HYDRA', 'Hydra', 'Hydra', 'Magical Beast', 'Huge', 28, 21, 'Massive many-headed serpentine beast with a central body and multiple long striking necks.', 'Defends territory with overlapping bites and relentless pressure from several heads.', 'Swamps, lakes, flooded ruins, marshes, and deep river valleys.', 'PROPOSED FOR REVIEW — copyright-safe catalog draft; mechanics and wording are independently authored for Serrian Tide.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-MANTICORE', 'Manticore', 'Manticore', 'Magical Beast', 'Large', 22, 14, 'Predatory composite beast with a leonine body, winged mobility, and a dangerous tail.', 'Stalks from range or altitude before closing with claws, jaws, and tail attacks.', 'Badlands, mountains, ruins, and dry wilderness.', 'PROPOSED FOR REVIEW — copyright-safe catalog draft; mechanics and wording are independently authored for Serrian Tide.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-SPHINX', 'Sphinx', 'Sphinx', 'Magical Beast', 'Large', 24, 16, 'Winged lion-bodied guardian with a human-like head and formidable intelligence.', 'Observant and deliberate; often tests, warns, or questions intruders before resorting to force.', 'Temples, deserts, monumental ruins, hidden sanctuaries, and ancient roads.', 'PROPOSED FOR REVIEW — copyright-safe catalog draft; mechanics and wording are independently authored for Serrian Tide.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-HARPY', 'Harpy', 'Harpy', 'Magical Beast', 'Medium', 14, 6, 'Winged humanoid creature with predatory claws and a harsh, uncanny presence.', 'Attacks from above, harasses isolated prey, and uses voice or movement to disrupt groups.', 'Cliffs, sea caves, ruins, mountain passes, and windswept coasts.', 'PROPOSED FOR REVIEW — copyright-safe catalog draft; mechanics and wording are independently authored for Serrian Tide.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-SIREN', 'Siren', 'Siren', 'Magical Beast', 'Medium', 16, 8, 'Mythic winged being famed for an enthralling voice that draws listeners toward danger.', 'Avoids straightforward contests when song, deception, or terrain can divide prey first.', 'Rocky coasts, islands, sea cliffs, and isolated shorelines.', 'PROPOSED FOR REVIEW — copyright-safe catalog draft; mechanics and wording are independently authored for Serrian Tide.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-KRAKEN', 'Kraken', 'Kraken', 'Magical Beast', 'Colossal', 35, 33, 'Colossal sea monster with a massive body and crushing tentacles capable of threatening ships.', 'Rises from deep water to seize, drag, crush, and overturn large prey or vessels.', 'Deep seas, remote straits, stormy coasts, and abyssal waters.', 'PROPOSED FOR REVIEW — copyright-safe catalog draft; mechanics and wording are independently authored for Serrian Tide.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-LEVIATHAN', 'Leviathan', 'Leviathan', 'Magical Beast', 'Colossal', 45, 54, 'World-scale sea beast whose immense serpentine body can dominate an entire stretch of ocean.', 'Overwhelms opposition through mass, violent water displacement, and catastrophic bites or tail impacts.', 'Deep oceans and legendary waters beyond ordinary navigation.', 'PROPOSED FOR REVIEW — copyright-safe catalog draft; mechanics and wording are independently authored for Serrian Tide.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-BEHEMOTH', 'Behemoth', 'Behemoth', 'Magical Beast', 'Colossal', 43, 49, 'Titanic land beast defined by overwhelming mass, endurance, and unstoppable physical force.', 'Moves with little concern for ordinary threats and responds to opposition by crushing through it.', 'Remote plains, ancient valleys, vast wilderness, and mythic interior lands.', 'PROPOSED FOR REVIEW — copyright-safe catalog draft; mechanics and wording are independently authored for Serrian Tide.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-CERBERUS', 'Cerberus', 'Hound', 'Magical Beast', 'Large', 26, 19, 'Three-headed hound of supernatural size and ferocity, able to watch and attack in several directions.', 'Relentless guardian that blocks passage, tracks multiple threats, and overwhelms close targets with coordinated bites.', 'Gates, caverns, underworld roads, cursed ruins, and guarded thresholds.', 'PROPOSED FOR REVIEW — copyright-safe catalog draft; mechanics and wording are independently authored for Serrian Tide.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-KELPIE', 'Kelpie', 'Water Horse', 'Magical Beast', 'Large', 15, 7, 'Supernatural water-horse associated with rivers and lochs, often appearing deceptively ordinary at first.', 'Uses patience and deception near water, then exploits speed and aquatic mobility once prey is committed.', 'Lochs, rivers, marshes, flooded valleys, and misty shorelines.', 'PROPOSED FOR REVIEW — copyright-safe catalog draft; mechanics and wording are independently authored for Serrian Tide.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-BLACK-SHUCK', 'Black Shuck', 'Spectral Hound', 'Magical Beast', 'Large', 14, 6, 'Ominous supernatural black hound associated with lonely roads, storms, and places of dread.', 'Stalks silently, appears without warning, and uses fear and sudden pursuit to break resistance.', 'Old roads, churchyards, moors, forests, coastlines, and storm-darkened countryside.', 'PROPOSED FOR REVIEW — copyright-safe catalog draft; mechanics and wording are independently authored for Serrian Tide.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-BANSHEE', 'Banshee', 'Spirit', 'Spirit', 'Medium', 22, 14, 'Restless female spirit associated with a piercing supernatural lament and the approach of death.', 'Keeps distance when possible and uses its voice or spectral presence to overwhelm the living.', 'Old homes, family lands, ruins, burial places, and lonely countryside.', 'PROPOSED FOR REVIEW — copyright-safe catalog draft; mechanics and wording are independently authored for Serrian Tide.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-WILL-O-WISP', 'Will-o''-the-Wisp', 'Spirit', 'Spirit', 'Tiny', 18, 9, 'Small wandering supernatural light that lures travelers away from safe paths.', 'Avoids direct capture and leads observers toward hazards, isolation, or exhaustion.', 'Marshes, bogs, forests, graveyards, and lonely roads.', 'PROPOSED FOR REVIEW — copyright-safe catalog draft; mechanics and wording are independently authored for Serrian Tide.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-REVENANT', 'Revenant', 'Undead', 'Undead', 'Medium', 20, 11, 'Dead person returned with a persistent purpose, grudge, oath, or unfinished task.', 'Focused and relentless; ignores distractions that do not interfere with its driving purpose.', 'Graves, ruins, former homes, battlefields, and places tied to its unresolved goal.', 'PROPOSED FOR REVIEW — copyright-safe catalog draft; mechanics and wording are independently authored for Serrian Tide.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-WRAITH', 'Wraith', 'Spirit', 'Spirit', 'Medium', 24, 16, 'Dark incorporeal apparition whose touch and presence drain warmth, vitality, or courage.', 'Stalks living targets from concealment and avoids becoming vulnerable to ordinary physical retaliation.', 'Ruins, burial grounds, battlefields, abandoned roads, and shadowed interiors.', 'PROPOSED FOR REVIEW — copyright-safe catalog draft; mechanics and wording are independently authored for Serrian Tide.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-POLTERGEIST', 'Poltergeist', 'Spirit', 'Spirit', 'Medium', 17, 9, 'Unseen or partially manifested spirit known for violent movement of objects and disruptive haunting activity.', 'Harasses from concealment, turns the environment into a weapon, and escalates when challenged.', 'Homes, ruins, schools, inns, and other occupied or abandoned structures.', 'PROPOSED FOR REVIEW — copyright-safe catalog draft; mechanics and wording are independently authored for Serrian Tide.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-GOLEM', 'Golem', 'Construct', 'Construct', 'Large', 20, 11, 'Artificial humanoid body animated by supernatural force rather than ordinary biology.', 'Literal, durable, and persistent; follows its purpose until destroyed, disabled, or released.', 'Workshops, temples, vaults, ruins, fortifications, and places where it was created or assigned.', 'PROPOSED FOR REVIEW — copyright-safe catalog draft; mechanics and wording are independently authored for Serrian Tide.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-GARGOYLE', 'Gargoyle', 'Construct', 'Construct', 'Medium', 14, 6, 'Stone-bodied winged guardian that can remain motionless among ordinary architectural carvings.', 'Patient and ambush-oriented; uses stillness and elevation before closing with claws and weight.', 'Cathedrals, towers, ruins, bridges, rooftops, and old stone structures.', 'PROPOSED FOR REVIEW — copyright-safe catalog draft; mechanics and wording are independently authored for Serrian Tide.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-FIRE-ELEMENTAL', 'Fire Elemental', 'Elemental', 'Elemental', 'Medium', 22, 14, 'Living manifestation of flame held together by supernatural force rather than flesh.', 'Moves toward fuel, threats, or commands and attacks through heat, flame, and engulfing contact.', 'Volcanic regions, burning sites, magical breaches, furnaces, and elemental domains.', 'PROPOSED FOR REVIEW — copyright-safe catalog draft; mechanics and wording are independently authored for Serrian Tide.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-WATER-ELEMENTAL', 'Water Elemental', 'Elemental', 'Elemental', 'Medium', 21, 12, 'Living mass of water shaped and directed by supernatural force.', 'Flows around obstacles, strikes with concentrated mass, and becomes far more mobile in water.', 'Rivers, lakes, coasts, flooded ruins, magical breaches, and elemental domains.', 'PROPOSED FOR REVIEW — copyright-safe catalog draft; mechanics and wording are independently authored for Serrian Tide.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-EARTH-ELEMENTAL', 'Earth Elemental', 'Elemental', 'Elemental', 'Large', 24, 16, 'Living formation of stone and earth with immense density and supernatural cohesion.', 'Advances steadily, breaks barriers, and relies on mass and durability over speed.', 'Caves, mountains, quarries, deep earth, magical breaches, and elemental domains.', 'PROPOSED FOR REVIEW — copyright-safe catalog draft; mechanics and wording are independently authored for Serrian Tide.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-AIR-ELEMENTAL', 'Air Elemental', 'Elemental', 'Elemental', 'Medium', 21, 12, 'Living vortex of wind and pressure with no fixed flesh-and-bone body.', 'Uses speed, turbulence, and sudden changes of direction to batter or scatter opponents.', 'Storms, high places, open skies, magical breaches, and elemental domains.', 'PROPOSED FOR REVIEW — copyright-safe catalog draft; mechanics and wording are independently authored for Serrian Tide.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-ANIMATED-ARMOR', 'Animated Armor', 'Construct', 'Construct', 'Medium', 12, 5, 'Empty suit of armor moved by magic or another animating force.', 'Fights with mechanical persistence and little concern for pain, fear, or fatigue.', 'Vaults, halls, armories, ruins, tombs, and magically guarded sites.', 'PROPOSED FOR REVIEW — copyright-safe catalog draft; mechanics and wording are independently authored for Serrian Tide.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-LIVING-STATUE', 'Living Statue', 'Construct', 'Construct', 'Medium', 16, 8, 'Carved stone figure animated into deliberate movement while retaining a dense mineral body.', 'Often remains motionless until a condition is met, then attacks with heavy controlled force.', 'Temples, monuments, gardens, ruins, tombs, and ancient complexes.', 'PROPOSED FOR REVIEW — copyright-safe catalog draft; mechanics and wording are independently authored for Serrian Tide.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-CARNIVOROUS-PLANT', 'Carnivorous Plant', 'Plant', 'Plant', 'Large', 10, 4, 'Large predatory plant adapted to seize, trap, and digest animal prey.', 'Waits motionless for prey to approach, then lashes outward with vines, jaws, or grasping growths.', 'Swamps, jungles, deep forests, overgrown ruins, and magically enriched soil.', 'PROPOSED FOR REVIEW — copyright-safe catalog draft; mechanics and wording are independently authored for Serrian Tide.', 'serrian-tide-creature-canon');
INSERT OR IGNORE INTO creatures (canonical_id, canonical_name, family, creature_type, size, challenge_rating, kill_xp, description, typical_behavior, habitat_ecology, notes, source_system) VALUES ('CR-CAVE-WORM', 'Cave Worm', 'Worm', 'Magical Beast', 'Huge', 20, 11, 'Enormous subterranean worm adapted to tunneling through soft stone, earth, and cavern debris.', 'Tracks vibration, bursts from cover, and uses its bulk to bite, crush, or collapse terrain.', 'Deep caverns, mines, buried ruins, badlands, and extensive tunnel systems.', 'PROPOSED FOR REVIEW — copyright-safe catalog draft; mechanics and wording are independently authored for Serrian Tide.', 'serrian-tide-creature-canon');

